using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evaluation;

public class ChatEvaluationTests : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder _builder = null!;
    private DistributedApplication _app = null!;

    public async Task InitializeAsync()
    {
        _builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _builder.BuildAsync();
        await _app.StartAsync();
    }

    public async Task DisposeAsync()
    {
        await _app.DisposeAsync();
    }

    [Fact]
    public async Task ChatClient_RespondsToBasicPrompt()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var response = await chatClient.GetResponseAsync("Hello, who are you?");

        Assert.NotNull(response);
        Assert.NotEmpty(response.Text);
    }

    [Fact]
    public async Task ChatClient_PerformsBasicReasoning()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var response = await chatClient.GetResponseAsync("What is 2 + 2? Reply with just the number.");

        Assert.NotNull(response);
        Assert.Contains("4", response.Text);
    }

    [Fact]
    public async Task ChatClient_FollowsInstructions()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var response = await chatClient.GetResponseAsync(
            "List three colors. Reply with a JSON array of strings.");

        Assert.NotNull(response);
        Assert.StartsWith("[", response.Text.Trim());
        Assert.EndsWith("]", response.Text.Trim());
    }
}

